#### 2. Create Watermark Component

Create a new file `src/components/watermark/watermark.jsx`:

```javascript
import React from 'react';
import PropTypes from 'prop-types';
import styles from './watermark.css';

const Watermark = ({selectedId}) => {
    if (!selectedId) return null;

    return (
        <div className={styles.watermark}>
            <img
                src={`path/to/sprites/${selectedId}.png`}
                alt="Selected Sprite"
                style={{opacity: 0.35, maxWidth: '48px', maxHeight: '48px'}}
            />
        </div>
    );
};

Watermark.propTypes = {
    selectedId: PropTypes.string
};

export default Watermark;
```

